H('251.d.8.A',4,"A market order to buy a stock is executed:","At the best available current price",["At a price you set","Only next year","Never"],"Market orders fill at the current price.")
H('251.d.8.B',3,"A bond with $1,000 face value and 5% coupon pays annual interest of:","$50",["$5","$500","$100"],"0.05 x 1,000 = 50.")
H('251.d.8.B',4,"When market interest rates rise, existing bond prices generally:","Fall",["Rise","Stay fixed","Double"],"Prices move inversely to rates.")
H('251.d.8.C',3,"Which investment typically offers the highest risk and highest potential return?","Stocks",["Savings accounts","CDs","Government bonds"],"Stocks are volatile.")
H('251.d.8.C',4,"A mutual fund differs from a single stock because it:","Pools many investors' money into a diversified portfolio",["Holds only one company","Guarantees returns","Has no risk"],"Funds offer diversification.")
H('251.d.8.D',3,"A diversified portfolio holds:","Many different investments",["One stock","Only cash","One bond"],"Diversification spreads risk.")
H('251.d.8.D',4,"Compared with a non-diversified portfolio, a diversified one generally has:","Lower risk for similar returns",["Higher risk","Guaranteed returns","No fees"],"Diversification reduces volatility.")
H('251.d.9.A',3,"Insurance that covers a set number of years and has no cash value is:","Term life insurance",["Whole life insurance","Auto insurance","Renter's insurance"],"Term coverage expires.")
H('251.d.9.A',4,"A permanent policy differs from term in that it:","Builds cash value and lasts for life",["Expires quickly","Costs nothing","Has no premiums"],"Whole life accumulates value.")
H('251.d.9.B',3,"Using a needs approach, family income of $50,000 and a 10-times-income guideline suggest coverage of:","$500,000",["$50,000","$5,000,000","$100,000"],"10 x 50,000 = 500,000.")
