H('251.d.9.C',3,"Health insurance costs include premiums, deductibles, and:","Copays",["Rent","Interest","Wages"],"Out-of-pocket costs vary.")
H('251.d.9.C',4,"A plan with a $200 monthly premium costs how much per year in premiums?","$2,400",["$200","$1,200","$240"],"200 x 12 = 2,400.")
H('251.d.9.D',3,"Disability income insurance replaces part of income if a worker:","Cannot work due to illness or injury",["Is on vacation","Quits","Gets a raise"],"It protects earnings.")
H('251.d.9.D',4,"Many workers need disability insurance because their largest asset is often:","Their ability to earn income",["Their car","Their phone","Their furniture"],"Income is the key asset.")
H('251.d.9.E',3,"An umbrella policy gives extra:","Liability coverage beyond other policies",["Rain protection","Life coverage","Pay raises"],"It extends liability limits.")
H('251.d.9.E',4,"Before buying special coverage, a consumer should compare its benefit to its:","Cost",["Color","Name","Age"],"Weigh benefit against price.")
H('251.d.9.F',3,"Insurers set premiums using the process of:","Actuarial analysis of risk",["Random guessing","Coin tosses","Rumor"],"Actuaries use data.")
H('251.d.9.F',4,"Younger drivers often pay higher auto premiums because statistics show:","Higher rates of accidents",["Lower rates of accidents","Better savings","Longer commutes always"],"Risk drives price.")
H('251.d.9.G',3,"When selecting an insurance company, a buyer should check its:","Financial strength rating and complaint record",["Slogan","Building size","Parking"],"Ratings show reliability.")
H('251.d.9.G',4,"A good insurance agent should be:","Licensed and able to explain options clearly",["Pushy","Unlicensed","Secretive"],"Licensing and clarity matter.")
H('251.d.10.A',3,"A retirement plan offered by a nonprofit or school district is a:","403(b)",["Roth IRA only","Savings bond","Checking account"],"403(b)s serve public schools and nonprofits.")
H('251.d.10.A',4,"Qualified withdrawals from a Roth IRA in retirement are generally:","Tax-free",["Taxed twice","Prohibited","Taxed at 100%"],"Roth contributions are after-tax.")
H('251.d.10.B',3,"Starting to save for retirement earlier helps because of:","Compounding over more years",["Lower contributions needed forever","Fewer taxes","Higher fees"],"Time magnifies growth.")
H('251.d.10.B',4,"Saving the same amount for 40 years instead of 20 years results in a balance that is:","Much more than double",["Exactly double","Smaller","The same"],"Exponential growth accelerates.")
H('251.d.10.C',3,"A $5,000 early withdrawal from a traditional retirement account with a 10% penalty costs how much in penalty?","$500",["$50","$5,000","$250"],"0.10 x 5,000 = 500.")
H('251.d.10.C',4,"In addition to the penalty, an early withdrawal from a traditional account is usually:","Taxed as income",["Tax-free","Refunded","Doubled"],"Withdrawals count as income.")
H('251.d.10.D',3,"If a worker contributes 6% of a $50,000 salary and the employer matches 50%, the employer adds:","$1,500",["$3,000","$750","$150"],"6% of 50,000 = 3,000; half is 1,500.")
H('251.d.10.D',4,"Saving $200 a month for 30 years without interest totals:","$72,000",["$7,200","$6,000","$24,000"],"200 x 360 = 72,000.")
H('251.d.14.A',3,"A balanced budget means:","Income covers expenses and savings",["Spending exceeds income","No savings","No bills"],"Income and outflow match.")
H('251.d.14.A',4,"Using a 50/30/20 plan on $3,000 monthly income, savings should be about:","$600",["$300","$900","$1,500"],"20% of 3,000 = 600.")
H('251.d.14.B',3,"A free resource to help manage a budget is:","A free budgeting app or spreadsheet template",["A high-fee service","A loan","A credit card"],"Free tools exist.")
H('251.d.14.B',4,"Nonprofit credit counseling agencies offer:","Low-cost help with budgets and debt",["High fees","Free cars","Guaranteed raises"],"Counselors assist consumers.")
H('251.d.14.C',3,"The cost of living for the same lifestyle is generally higher in:","Large expensive cities",["Rural areas always","Every place equally","Small towns always"],"Housing drives differences.")
H('251.d.14.C',4,"A salary of $60,000 buys less in a city where housing costs:","Are much higher",["Are much lower","Are unchanged","Are free"],"Real purchasing power varies.")
H('251.d.15.A',3,"Using someone else's Social Security number to open an account is:","Identity theft",["A bank service","A tax credit","A budgeting tool"],"It is a crime.")
H('251.d.15.A',4,"A phishing email that tricks you into sharing your password is a form of:","Identity theft attempt",["A job offer","A coupon","A receipt"],"Phishing steals information.")
H('251.d.15.B',3,"A strong prevention step is to:","Use unique passwords and two-factor authentication",["Reuse one password","Share PINs","Post your SSN"],"Strong authentication protects accounts.")
H('251.d.15.B',4,"To prevent identity theft, you should:","Shred documents with personal information",["Throw them in the trash","Leave them on a desk","Mail them to strangers"],"Shredding prevents dumpster diving.")
H('251.d.15.C',3,"A victim of identity theft should report it to the:","Federal Trade Commission at IdentityTheft.gov",["Pizza shop","Radio station","School bus driver"],"The FTC handles reports.")
H('251.d.15.C',4,"After discovering identity theft, a victim should also:","Place a fraud alert or freeze on credit reports",["Ignore it","Share the SSN publicly","Close all accounts silently"],"Alerts limit new fraud.")
H('251.d.16.A',3,"A student exploring careers should consider education, military service, and:","Current job opportunities",["Only hobbies","Past events","Rumors"],"Options include many paths.")
H('251.d.16.A',4,"The military can help pay for education through:","Programs such as the GI Bill",["Free cars","Tax refunds","Bank fees"],"Benefits support education.")
H('251.d.16.B',3,"Matching interests and skills to careers helps a student:","Choose a suitable path and plan for it",["Avoid planning","Ignore costs","Delay forever"],"Alignment improves satisfaction.")
H('251.d.16.B',4,"A student who enjoys helping people and science might research careers in:","Healthcare",["Only mining","Only forestry","Only sales"],"Interests suggest fields.")
H('251.d.16.C',3,"A program costs $12,000 per year in tuition and $8,000 in living costs for 4 years. Total cost is:","$80,000",["$20,000","$48,000","$96,000"],"(12,000 + 8,000) x 4 = 80,000.")
H('251.d.16.C',4,"To estimate total funding for college, a student should include tuition, books, housing, and:","Transportation and fees",["Only tuition","Only books","Nothing else"],"Costs go beyond tuition.")
H('251.d.16.D',3,"Aid that does not need to be repaid includes:","Grants and scholarships",["Student loans","Credit cards","Payday loans"],"Gift aid is free money.")
H('251.d.16.D',4,"The form used to apply for federal student aid is the:","FAFSA",["W-2","1099","W-4"],"The FAFSA determines federal aid.")
H('251.d.16.E',3,"Earning dual credit in high school can save money by:","Reducing the number of college courses to pay for later",["Raising tuition","Adding debt","Lengthening college"],"Early credits lower costs.")
