H('251.d.16.F',3,"A graph comparing the cost of a degree with expected earnings helps a student:","Judge whether the education is a good investment",["Ignore costs","Avoid math","Pick a hobby"],"Graphs show payback.")
H('251.d.16.F',4,"A career pays $30,000 more per year with a degree. A graph of cumulative extra earnings over 10 years reaches:","$300,000",["$30,000","$3,000,000","$60,000"],"30,000 x 10 = 300,000.")
H('251.d.16.G',3,"A degree costs $40,000 and adds $100,000 in earnings over time. Net gain is:","$60,000",["$140,000","$40,000","$100,000"],"100,000 - 40,000 = 60,000.")
H('251.d.16.G',4,"Return on investment in that example is:","150%",["60%","40%","250%"],"60,000 / 40,000 = 1.5.")

# ---- 252 Personal Financial Literacy
H('252.d.1.A',3,"The benefit of financial planning is that it helps you:","Reach goals and prepare for emergencies",["Spend more","Avoid saving","Ignore bills"],"Planning guides decisions.")
H('252.d.1.A',4,"A written financial plan should include goals, a budget, and:","A timeline for reaching goals",["A guess","A secret","No dates"],"Plans need timelines.")
H('252.d.1.B',3,"Paying bills on time and being honest on loan applications show:","Personal financial responsibility",["Carelessness","Dishonesty","Neglect"],"Responsibility builds trust.")
H('252.d.1.B',4,"Ethical financial behavior includes:","Reporting income accurately on tax forms",["Hiding income","Lying on applications","Skipping taxes"],"Honesty is ethical.")
H('252.d.2.A',3,"A student comparing college, military, and job options is:","Understanding postsecondary opportunities",["Ignoring options","Guessing","Delaying"],"Exploring options informs planning.")
H('252.d.2.A',4,"Which source gives information on careers and pay?","The Bureau of Labor Statistics",["A rumor","A comic","A song"],"BLS publishes career data.")
