H('252.d.10.E',3,"Company earnings, interest rates, and economic conditions are factors that affect:","The value of investments",["Weather only","Sports scores","TV ratings"],"Many factors move prices.")
H('252.d.10.E',4,"When a company reports strong earnings, its stock price often:","Rises",["Falls","Stays fixed","Vanishes"],"Good news lifts prices.")
H('252.d.11.A',3,"Insurance protects people by:","Sharing the risk of large losses among many policyholders",["Preventing all loss","Paying all bills","Removing risk"],"Risk pooling.")
H('252.d.11.A',4,"The amount you pay to an insurer for coverage is the:","Premium",["Deductible","Claim","Benefit"],"Premiums buy coverage.")
H('252.d.11.B',3,"Health, life, and disability insurance protect against:","Personal financial loss from illness, death, or injury",["Property damage","Bank fees","Taxes"],"Personal insurance protects people.")
H('252.d.11.B',4,"A person with dependents often buys life insurance to:","Replace income for their family if they die",["Pay for vacations","Avoid taxes","Raise income"],"It protects dependents.")
H('252.d.11.C',3,"Homeowners and auto policies are types of:","Property insurance",["Life insurance","Health insurance","Disability insurance"],"They protect property and liability.")
H('252.d.11.C',4,"Auto liability insurance pays for:","Damage or injury you cause to others",["Your own repairs always","Your lunch","Your tolls"],"Liability covers others.")
H('252.d.11.D',3,"After a covered loss, the insured begins the claim process by:","Notifying the insurance company",["Waiting a year","Hiding the loss","Paying the premium twice"],"Report the claim promptly.")
H('252.d.11.D',4,"The amount a policyholder pays before insurance starts paying is the:","Deductible",["Premium","Benefit","Beneficiary"],"Deductibles are out-of-pocket first.")

# ---- 253 Securities and Investments
H('253.d.7',3,"A company splits its stock 2-for-1. A holder with 100 shares worth $50 each now has:","200 shares worth $25 each",["100 shares worth $100 each","200 shares worth $50 each","50 shares worth $50 each"],"Shares double and price halves; total value stays $5,000.")
H('253.d.7',4,"From an investor's perspective, a major advantage of a mutual fund over individual stocks is:","Built-in diversification",["Guaranteed profit","No fees","No risk"],"Funds spread risk across holdings.")
H('253.d.1.A',3,"The federal agency that regulates the securities industry is the:","Securities and Exchange Commission",["Federal Reserve","IRS","FDA"],"The SEC oversees securities markets.")
H('253.d.1.A',4,"The Securities Exchange Act of 1934 created the:","SEC",["IRS","FDIC","NASDAQ"],"The 1934 Act established the SEC.")
H('253.d.1.B',3,"Trading on inside information not available to the public is:","Illegal insider trading",["Smart investing","Allowed","Normal"],"It is unfair and illegal.")
H('253.d.1.B',4,"A broker who recommends products solely to earn higher commission may violate:","Ethical and legal duties to the customer",["No rules","The weather","Taxes only"],"Brokers owe duties to clients.")
H('253.d.1.C',3,"State securities laws that protect investors from fraud are often called:","Blue sky laws",["Red tape laws","Green laws","Tax codes"],"Blue sky laws regulate offerings.")
H('253.d.1.C',4,"In Texas, securities regulation is handled by the:","Texas State Securities Board",["Texas Lottery Commission","Texas Rangers","Texas Highway Dept."],"The Board enforces state securities law.")
H('253.d.2.A',3,"An investor saving for retirement 30 years away would likely have an objective of:","Long-term growth",["Immediate income","Quick profits","Capital preservation only"],"Long horizons favor growth.")
H('253.d.2.A',4,"A retiree seeking steady income would likely emphasize:","Income-producing investments",["Speculation","High-growth only","Day trading"],"Income objectives favor dividends and bonds.")
H('253.d.2.B',3,"Investment risk refers to the chance that an investment will:","Lose value or earn less than expected",["Always gain","Never change","Be taxed"],"Risk is uncertainty of returns.")
H('253.d.2.B',4,"Generally, higher potential return comes with:","Higher risk",["Lower risk","No risk","Guaranteed gains"],"Risk and return are related.")
H('253.d.2.C',3,"Spreading money across stocks, bonds, and real estate is:","Diversification",["Concentration","Speculation","Margin"],"Diversification reduces risk.")
H('253.d.2.C',4,"A portfolio with 100% in one company's stock is exposed to:","Concentration risk",["No risk","Inflation only","Zero volatility"],"One company can fail.")
H('253.d.2.D',3,"When selecting investments, an investor should consider risk, return, and:","Time horizon and liquidity",["Logo","Slogan","Office color"],"Matching needs matters.")
H('253.d.2.D',4,"Liquidity measures how easily an investment can be:","Converted to cash",["Taxed","Diversified","Insured"],"Liquid assets sell fast.")
H('253.d.2.E',3,"Investors read a company's balance sheet and income statement to learn about its:","Financial health and profitability",["Logo","Slogan","Office color"],"Statements reveal performance.")
H('253.d.2.E',4,"A company with rising revenue but growing debt may be:","Increasing risk even as it grows",["Perfectly safe","Debt-free","Shrinking"],"Debt affects risk.")
H('253.d.2.F',3,"A mutual fund prospectus describes the fund's objectives, fees, and:","Risks",["Menu","Slogan","Dress code"],"The prospectus discloses key details.")
H('253.d.2.F',4,"The expense ratio in a prospectus tells investors:","The annual fee as a percent of assets",["The fund's logo","The manager's age","The fund's address"],"Lower fees keep more return.")
H('253.d.2.G',3,"Comparing a stock's price to its earnings per share is a type of:","Valuation analysis",["Weather report","Tax return","Spelling test"],"It helps judge price.")
H('253.d.2.G',4,"Technical analysis relies mainly on:","Price and volume patterns",["Company history only","Rumors","Tax law"],"It studies market data.")
H('253.d.2.H',3,"Buying a broad index fund and holding it for decades is a:","Passive investing strategy",["Day trading","Short selling","Margin trading"],"Passive investing tracks the market.")
H('253.d.2.H',4,"Dollar-cost averaging means investing:","A fixed amount at regular intervals",["Everything at once","Only when prices drop","Never"],"It smooths purchase prices.")
H('253.d.2.I',3,"A venture capital fund's performance is commonly measured by:","Internal rate of return",["Menu items","Shoe size","Weather"],"IRR measures annualized return.")
H('253.d.2.I',4,"A venture capital fund invests $10 million and returns $30 million. Its multiple of invested capital is:","3.0x",["0.3x","20x","10x"],"30 / 10 = 3.")
H('253.d.2.J',3,"Modern Portfolio Theory says investors can reduce risk for a given return by:","Diversifying across assets",["Concentrating in one stock","Avoiding bonds","Trading daily"],"MPT emphasizes diversification.")
H('253.d.2.J',4,"CAPM estimates an investment's expected return with risk-free rate 3%, beta 1.2, and market return 8%:","9%",["8%","12%","4.5%"],"3 + 1.2 x (8 - 3) = 9.")
H('253.d.3.A',3,"A stock priced at $50 with earnings per share of $2.50 has a price-earnings ratio of:","20",["10","125","2.5"],"50 / 2.5 = 20.")
H('253.d.3.A',4,"A high price-earnings ratio often suggests investors expect:","Higher future growth",["Falling earnings","No growth","Bankruptcy"],"Investors pay more for growth.")
H('253.d.3.B',3,"A stock expects a $2 dividend next year, a 10% required return, and 4% growth. By the constant growth model its value is about:","$33.33",["$20","$50","$14"],"2 / (0.10 - 0.04) = 33.33.")
H('253.d.3.B',4,"A stock priced at $40 with a $2 expected dividend and 5% growth has an expected return of:","10%",["5%","2%","7%"],"2/40 = 5% plus 5% growth = 10%.")
H('253.d.3.C',3,"A $1,000 bond with a 6% coupon pays annual interest of:","$60",["$6","$600","$100"],"0.06 x 1,000 = 60.")
H('253.d.3.C',4,"If market rates rise above a bond's coupon rate, the bond's price usually:","Falls below face value",["Rises above face value","Equals face value","Becomes zero"],"The bond becomes less attractive.")
H('253.d.3.D',3,"The present value of $1,000 received in 2 years with a 5% discount rate is about:","$907",["$1,000","$1,100","$950"],"1,000 / 1.1025 = 907.03.")
H('253.d.3.D',4,"The future value of $500 after 2 years at 4% compounded annually is:","$540.80",["$520","$540","$580"],"500 x 1.0816 = 540.80.")
H('253.d.3.E',3,"An investor choosing between two stocks with similar risk might prefer the one with:","The lower price-earnings ratio",["The higher price-earnings ratio","No earnings","No dividends"],"Lower P/E may be cheaper.")
H('253.d.3.E',4,"Which ratio shows dividends relative to price?","Dividend yield",["Current ratio","Debt ratio","Quick ratio"],"Yield = dividend / price.")
H('253.d.4.A',3,"The process of confirming that a trade has been completed and ownership transferred is:","Settlement",["Advertising","Auditing","Recruiting"],"Settlement finalizes trades.")
H('253.d.4.A',4,"Under current rules, most U.S. stock trades settle in:","One business day",["One year","One month","Ten days"],"Settlement is T+1.")
H('253.d.4.B',3,"A securities office's back-office staff handle:","Trade processing and record keeping",["Sales calls only","Advertising","Building maintenance"],"Operations support trading.")
H('253.d.4.B',4,"Compliance staff in a brokerage ensure that the firm:","Follows securities laws and rules",["Sells more","Hires faster","Cuts prices"],"Compliance prevents violations.")
H('253.d.4.C',3,"A brokerage that earns a fee for executing trades for clients is acting as an:","Agent",["Issuer","Regulator","Auditor"],"Brokers act as agents.")
H('253.d.4.C',4,"A market maker helps the market by:","Standing ready to buy and sell a security",["Setting taxes","Printing money","Auditing firms"],"Market makers provide liquidity.")
H('253.d.4.D',3,"A broker charges a 1.5% commission on a $4,000 stock purchase. The commission is:","$60",["$6","$600","$15"],"0.015 x 4,000 = 60.")
H('253.d.4.D',4,"A flat fee of $5 per trade is cheaper than a 1% commission when the trade is larger than:","$500",["$50","$5,000","$5"],"1% of 500 is 5.")
H('253.d.5.A',3,"Entry-level securities jobs often require at least a:","High school diploma plus training or a college degree",["Medical degree","Law degree","PhD"],"Requirements vary by role.")
H('253.d.5.A',4,"Many securities professionals pursue degrees in:","Finance, business, or economics",["Welding","Painting","Cooking"],"These fields are common.")
H('253.d.5.B',3,"The Series 7 exam licenses a person to sell:","A broad range of securities",["Only mutual funds","Only insurance","Only real estate"],"Series 7 is the general securities exam.")
H('253.d.5.B',4,"The Series 6 exam is limited mostly to selling:","Mutual funds and variable annuities",["All stocks","Options only","Futures only"],"Series 6 has narrower scope.")
H('253.d.5.C',3,"A professional designation such as Certified Financial Planner shows:","Advanced training and ethics standards in financial planning",["Free advice","A government job","No education"],"CFP is a respected credential.")
H('253.d.5.C',4,"The CFA designation focuses on:","Investment analysis and portfolio management",["Cooking","Real estate sales","Auto repair"],"CFA is for investment professionals.")
H('253.d.6.A',3,"Security and investment services are offered in environments including brokerages, banks, and:","Investment advisory firms",["Gas stations","Farms","Schools only"],"Many firms provide services.")
H('253.d.6.A',4,"A full-service broker differs from a discount broker by offering:","Personalized advice at higher cost",["No advice","No fees","Only online trades"],"Full-service includes advice.")
H('253.d.6.B',3,"A company announcing lower-than-expected earnings often sees its stock price:","Fall",["Rise","Stay fixed","Double"],"Bad news lowers price.")
H('253.d.6.B',4,"Which is a cause of stock price increases?","Strong demand from buyers",["Weak demand","Lawsuits","Defaults"],"Demand pushes price up.")
H('253.d.6.C',3,"When bond yields rise, bond prices:","Fall",["Rise","Stay the same","Double"],"Prices and yields move inversely.")
H('253.d.6.C',4,"A bond's yield rises from 4% to 5%. Existing bonds with a 4% coupon:","Become less valuable",["Become more valuable","Are unaffected","Pay more"],"New bonds pay more.")
H('253.d.6.D',3,"Investment banks help companies raise money in the:","Primary market",["Secondary market only","Used market","Flea market"],"IPOs happen in the primary market.")
H('253.d.6.D',4,"An investment bank that guarantees the sale of a new stock issue is:","Underwriting it",["Auditing it","Regulating it","Insuring it"],"Underwriters buy and resell issues.")
H('253.d.6.E',3,"Buying stock with money borrowed from a broker is trading on:","Margin",["Credit union","Savings","Escrow"],"Margin is borrowed money.")
H('253.d.6.E',4,"A short sale profits if the stock price:","Falls",["Rises","Stays fixed","Is not traded"],"Shorts sell high and buy back low.")
H('253.d.8.A',3,"A student exploring securities careers should consider education, military, and:","Current job opportunities",["Only hobbies","Rumors","Nothing"],"Options vary.")
H('253.d.8.A',4,"A source for securities industry job outlook is the:","Bureau of Labor Statistics",["A rumor","A comic","A song"],"BLS provides outlooks.")
H('253.d.8.B',3,"A postsecondary plan includes application deadlines, costs, and:","Funding sources",["Rumors","Colors","Mascots"],"Plans need funding.")
H('253.d.8.B',4,"A student planning for a finance degree should compare tuition at several schools and also:","Available scholarships and aid",["Mascots","Dorm colors","Parking"],"Aid affects net cost.")
H('252.d.8.E',5,"A statement shows an ending balance of $1,240. Your register shows $1,010 after subtracting a $230 check that has not cleared. What does the register balance mean after reconciling?","The two balances agree once the outstanding check is accounted for",["The bank made a $230 error","The register is wrong by $230","The account is overdrawn"],"1,240 - 230 = 1,010, so they match.")

